  box: { type: 'table', title: 'Semifinais', head: ['Confronto', 'Ida', 'Volta'], rows: [['Palmeiras x Fluminense', '2 x 1 para o Palmeiras', 'Quarta (21), Nubank Parque'], ['Flamengo x Estudiantes', '0 x 0', 'Quinta (22), Maracanã']], note: 'Jogos de volta às 21h30 de Brasília. Fontes: Gazeta Esportiva, Lance!, Turista FC e Agência Brasil.' },
